(()=>{
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let initial=true,rows=[];
const pct=v=>v==null?'—':v+'%';
function table(headers,body){return '<table class="data-table"><thead><tr>'+headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+body.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function chooseOptions(){const old=$('topic').value;const topics=[...new Set(rows.filter(q=>!$('subject').value||q.subject===$('subject').value).map(q=>q.topic))].sort();$('topic').replaceChildren(new Option('All topics',''),...topics.map(t=>new Option(t,t)));if(topics.includes(old))$('topic').value=old}
function setDateRange(){
 const range=$('time-range').value,custom=range==='custom';
 $('from').disabled=!custom;$('to').disabled=!custom;
 if(custom)return;
 if(range==='all'){$('from').value='';$('to').value='';return;}
 const today=new Date(Date.now()+7*60*60*1000).toISOString().slice(0,10);
 const [year,month,day]=today.split('-').map(Number);
 const first=new Date(Date.UTC(year,month-1-Number(range),1));
 const lastDay=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();
 first.setUTCDate(Math.min(day,lastDay));
 $('from').value=first.toISOString().slice(0,10);$('to').value=today;
}
async function load(){setDateRange();if($('from').value&&$('to').value&&$('from').value>$('to').value){$('dashboard-status').textContent='Choose an end date on or after the start date.';return;}const params=new URLSearchParams();for(const id of ['mode','basis','subject','topic','from','to'])if($(id).value)params.set(id,$(id).value);$('dashboard-status').textContent='Loading…';try{const d=await Account.request('/api/admin/dashboard?'+params);if(initial){rows=d.rows;$('subject').replaceChildren(new Option('All subjects',''),...[...new Set(rows.map(q=>q.subject))].sort().map(s=>new Option(s,s)));chooseOptions();initial=false}
 const s=d.summary;$('metrics').innerHTML=`<div><strong>${s.completed} / ${s.started}</strong>Sessions submitted / started</div><div><strong>${pct(s.percent)}</strong>Points earned in selected responses</div><div><strong>${s.n}</strong>Selected question responses</div><div><strong>${s.unanswered}</strong>Unanswered</div>`;
 $('dashboard-status').textContent=s.n?'Updated.':'No submitted learner responses match these filters yet.';$('mode-note').textContent=d.mode==='case_scenarios'?'Case scenarios provide feedback after each step. These guided-learning scores are separate from Exam and Reviewer results.':d.mode==='reviewer'?'Reviewer mode provides immediate answers. These scores represent practice, not independent assessment.':'Exam-mode results only. Reviewer practice is excluded.';$('definitions').textContent=d.definitions;
 $('heatmap').innerHTML=d.learners.length?'<table class="data-table heatmap"><thead><tr><th scope="col">Question / revision</th>'+d.learners.map(l=>`<th scope="col">${esc(l.name)}<br><small>${esc(l.username)}</small></th>`).join('')+'</tr></thead><tbody>'+d.rows.map((q,ri)=>'<tr><th scope="row">'+esc(q.display_code||q.id)+' · v'+q.revision+'<br><small>'+esc(q.subject)+' / '+esc(q.topic)+'</small></th>'+d.learners.map(l=>{const c=q.cells[l.id];if(!c)return '<td class="no-attempt" aria-label="Not attempted in this view">—</td>';const hue=Math.max(0,Math.min(100,c.percent))*1.2;return `<td style="background:${c.blank?'#fff1c2':`hsl(${hue} 55% 88%)`}"><button data-row="${ri}" data-user="${l.id}" aria-label="${esc(l.name)}, ${esc(q.display_code||q.id)} revision ${q.revision}, ${c.blank?'unanswered, ':''}${c.percent} percent">${c.blank?'U · ':''}${c.percent}%</button></td>`}).join('')+'</tr>').join('')+'</tbody></table>':'<p>No learner accounts yet. Administrator practice is excluded.</p>';
 $('heatmap').querySelectorAll('button[data-row]').forEach(b=>b.onclick=()=>{const q=d.rows[Number(b.dataset.row)],c=q.cells[b.dataset.user],l=d.learners.find(x=>String(x.id)===b.dataset.user);$('cell-title').textContent=l.name+' · '+(q.display_code||q.id)+' · revision '+q.revision;$('cell-question').textContent=q.text;$('cell-response').textContent='Response: '+(c.blank?'Unanswered':Array.isArray(c.answer)?c.answer.join(', '):c.answer);$('cell-score').textContent=c.score+' / '+c.maximum+' points · '+new Date(c.submitted).toLocaleString()+' · '+c.attempt_count+' submitted responses to this revision';$('cell-detail').showModal()});
 $('question-stats').innerHTML=table(['Question / revision','Responses','Accuracy','Unanswered','Most selected wrong choices','Admin feedback'],d.rows.map(q=>[(q.display_code||q.id)+' · v'+q.revision,q.n,pct(q.accuracy),q.unanswered,q.wrong_choices.map(c=>c.choice+'. '+c.text+' ('+c.count+')').join('; ')||'—',q.admin_feedback]));
 $('topic-stats').innerHTML=d.topics.length?table(['Subject','Topic','Responses','Points earned','Unanswered'],d.topics.map(t=>[t.subject,t.topic,t.n,pct(t.percent),t.unanswered])):'<p>No submitted responses.</p>';
 $('learner-stats').innerHTML=table(['Learner','Responses','Points earned','Unanswered','Change on repeated questions','Repeated questions'],d.learners.map(l=>[l.name+' ('+l.username+')',l.n,pct(l.percent),l.unanswered,l.improvement==null?'—':(l.improvement>0?'+':'')+l.improvement+' percentage points',l.repeated_questions]));
 const topicRows=[];for(const l of d.learners){const groups=new Map();for(const q of d.rows){const c=q.cells[l.id];if(!c)continue;const key=JSON.stringify([q.subject,q.topic]);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(c)}for(const [k,cs] of groups){const [subject,topic]=JSON.parse(k);topicRows.push([l.name,subject,topic,cs.length,Math.round(1000*cs.reduce((n,c)=>n+c.score,0)/cs.reduce((n,c)=>n+c.maximum,0))/10+'%'])}}$('learner-topics').innerHTML=topicRows.length?table(['Learner','Subject','Topic','Responses','Points earned'],topicRows):'<p>No submitted responses.</p>';
 }catch(e){$('dashboard-status').textContent=e.message;for(const id of ['metrics','heatmap','question-stats','topic-stats','learner-stats','learner-topics'])$(id).replaceChildren()}}
 $('time-range').onchange=setDateRange;setDateRange();$('filters').onsubmit=e=>{e.preventDefault();load()};$('subject').onchange=chooseOptions;$('close-cell').onclick=()=>$('cell-detail').close();Account.ready.then(load).catch(()=>{});
})();
